def select_words(s, n):
    def count_consonants(word):
        consonants = 'bcdfghjklmnpqrstvwxyz'
        return sum(1 for letter in word if letter.lower() in consonants)

    def preserve_case(word, original_word):
        return ''.join(c.upper() if o.isupper() else c.lower() for c, o in zip(word, original_word))

    def remove_punctuation(word):
        return ''.join(char for char in word if char.isalpha())

    words = s.split()
    filtered_words = []

    for word in words:
        cleaned_word = remove_punctuation(word)
        if count_consonants(cleaned_word) == n:
            filtered_words.append(preserve_case(cleaned_word, word))

    return filtered_words
